contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry for the property test
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(to != address(0));

        // Ensure the test contract has enough shares to attempt selling: mint some shares to this contract by simulating a buyShares call.
        // We cannot directly mint except via buyShares; prepare token balances by calling buyShares on c from this contract.
        // To keep this generic, first record caller's shares and totalSupply.
        uint256 beforeShares = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        // Try to call sellShares and observe whether it reverted. Per constraints, the call that mutates state must be top-level.
        bool reverted;
        uint256 baseAmount;
        uint256 quoteAmount;
        (uint256 _baseAmount, uint256 _quoteAmount) = c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            baseAmount = 0;
            quoteAmount = 0;
        } else {
            reverted = false;
            baseAmount = _baseAmount;
            quoteAmount = _quoteAmount;
        }

        // Observe shares and totalSupply after the call (or attempted call)
        uint256 afterShares = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        // If the call succeeded (did not revert), then this contract's share balance decreased by exactly shareAmount
        // and totalSupply decreased by exactly shareAmount. If it reverted, no requirement.
        assert(reverted || (beforeShares == afterShares + shareAmount && totalBefore == totalAfter + shareAmount));
    }

    receive() external payable {}
}

